<div class="text-end mb-3"><a class="btn btn-primary" href="<?= e(base_url('admin/product/add')) ?>">+ Thêm sản phẩm</a></div><div class="table-responsive"><table class="table table-bordered bg-white align-middle"><thead><tr><th>Ảnh</th><th>SKU</th><th>Tên</th><th>Danh mục</th><th>Giá</th><th>Tồn</th><th>Số ảnh</th><th>Trạng thái</th><th></th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><img width="55" height="55" src="<?= e(product_image_url($p['image'],'thumb')) ?>" alt=""></td><td><?= e($p['sku']) ?></td><td><?= e($p['name']) ?></td><td><?= e($p['category_name']) ?></td><td><?= format_vnd($p['price']) ?></td><td><?= (int)$p['stock'] ?></td><td><?= (int)$p['image_count'] ?>/<?= UPLOAD_MAX_IMAGES ?></td><td><?= e($p['status']) ?></td><td><a class="btn btn-sm btn-outline-primary" href="<?= e(base_url('admin/product/edit/'.$p['id'])) ?>">Sửa</a><form class="d-inline" method="post" action="<?= e(base_url('admin/product/delete')) ?>" onsubmit="return confirm('Xóa sản phẩm và ảnh?')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><button class="btn btn-sm btn-outline-danger">Xóa</button></form></td></tr><?php endforeach; ?></tbody></table></div>
